{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "`create_shipment` needs the sender address (the account's `pickup_address`), the recipient address, the weight in kilograms and the service.",
      "requirement": "The `create_shipment` tool call must include the sender address as the account's `pickup_address` (Liivalaia 12, 10118 Tallinn, EE), the recipient address, the weight in kilograms, and the service."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Weight must be given in kilograms. If the customer gives pounds, convert (1 lb = 0.4536 kg) and round to one decimal.",
      "requirement": "The weight must be provided in kilograms (no conversion from pounds is required here)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Prohibited items: batteries shipped loose (not inside a device), aerosols, and any liquids over 1 litre. Shipments containing prohibited items must not be created.",
      "requirement": "The shipment must not contain prohibited items: loose batteries, aerosols, or liquids over 1 liter."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Declared value (insurance) may not exceed 2,000 EUR per parcel. Values above that are not accepted.",
      "requirement": "If a declared value is provided, it must not exceed 2,000 EUR."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "The service `express` guarantees next-business-day delivery; `standard` takes 2–4 business days. When telling the customer the expected delivery date, compute it from today and the service (business days are Monday–Friday).",
      "requirement": "The service must be either `express` or `standard`, and the delivery date must be computed based on the service and current date (business days are Monday–Friday)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Before `create_shipment`, present the details (including weight and declared value) and obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Before calling `create_shipment`, the assistant must present the shipment details (sender address, recipient address, weight, service, contents, and declared value if any) and obtain explicit confirmation from the user."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Outside the EU, customs declarations are required and declared value may go up to 5,000 EUR with the `international` service only. Not applicable to domestic shipments.",
      "requirement": "For domestic shipments (both sender and recipient in Estonia), customs declarations are not required, and the declared value limit is 2,000 EUR."
    }
  ]
}
